<?php
require_once __DIR__ . '/includes/functions.php';$u=require_role('business_owner');$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$criteriaId=(int)($_POST['criteria_id']??0);$action=$_POST['action']??'';$c=$pdo->prepare('SELECT lc.*,u.id AS lender_id FROM lender_criteria lc JOIN users u ON u.id=lc.lender_user_id WHERE lc.id=? AND lc.is_active=1');$c->execute([$criteriaId]);$criterion=$c->fetch();if(!$criterion){flash('error',t('This lender option is no longer available.','Cette option de prêt n’est plus disponible.'));redirect('lenders.php');}if($action==='consent'){$stmt=$pdo->prepare('SELECT id FROM consents WHERE business_user_id=? AND lender_user_id=? AND revoked_at IS NULL');$stmt->execute([$u['id'],$criterion['lender_id']]);if(!$stmt->fetch()){$stmt=$pdo->prepare('INSERT INTO consents (business_user_id,lender_user_id,criteria_id,consent_purpose,consented_at) VALUES (?,?,?,?,NOW())');$stmt->execute([$u['id'],$criterion['lender_id'],$criteriaId,'Review my business profile for the selected lending criteria']);}$stmt=$pdo->prepare('INSERT INTO consent_events (business_user_id,lender_user_id,criteria_id,event_type,details) VALUES (?,?,?,?,?)');$stmt->execute([$u['id'],$criterion['lender_id'],$criteriaId,'granted','Owner chose to share business profile for lender review']);flash('success',t('Consent granted for this lender. You can revoke it at any time.','Consentement accordé à ce prêteur. Vous pouvez le révoquer à tout moment.'));}redirect('lenders.php');}
$matches=matched_lenders((int)$u['id']);$s=$pdo->prepare('SELECT lender_user_id,criteria_id FROM consents WHERE business_user_id=? AND revoked_at IS NULL');$s->execute([$u['id']]);$shared=$s->fetchAll();$sharedIds=array_map(fn($x)=>(int)$x['criteria_id'],$shared);$pageTitle=t('Lender directory','Répertoire des prêteurs');require __DIR__.'/includes/header.php';
?>
<div class="dashboard-heading"><div><span class="eyebrow"><?= e(t('LENDER DIRECTORY','RÉPERTOIRE DES PRÊTEURS')) ?></span><h1><?= e(t('Find a realistic fit','Trouver une option adaptée')) ?></h1><p><?= e(t('Review published criteria before deciding whether to share your information. No information is shared just by viewing this page.','Consultez les critères publiés avant de décider de partager vos informations. La consultation de cette page ne partage aucune donnée.')) ?></p></div><a class="btn btn-outline" href="<?= e(url('consents.php')) ?>"><?= e(t('Manage consent','Gérer le consentement')) ?></a></div>
<div class="notice-box"><span class="notice-icon">i</span><p><?= e(t('A “criteria fit” means your available profile matches the rules listed here. It is not an approval, and the lender may request additional evidence.','« Critères compatibles » signifie que votre profil disponible correspond aux règles indiquées. Ce n’est pas une approbation et le prêteur peut demander d’autres justificatifs.')) ?></p></div>
<div class="lender-grid"><?php if(!$matches): ?><div class="panel empty-state"><?= e(t('No lender criteria have been published yet.','Aucun critère de prêteur n’a encore été publié.')) ?></div><?php else: foreach($matches as $m): $c=$m['criteria'];$hasConsent=in_array((int)$c['id'],$sharedIds,true); ?><article class="panel lender-card"><div class="lender-card-top"><div class="institution-mark"><?= e(strtoupper(substr($c['institution_name']?:$c['lender_name'],0,1))) ?></div><div><h2><?= e($c['institution_name']?:$c['lender_name']) ?></h2><p><?= e($c['sector']==='all'?t('All business sectors','Tous les secteurs'):ucfirst($c['sector'])) ?></p></div></div><p class="amount-range"><?= e(number_format((float)$c['min_amount'],0)) ?> – <?= e(number_format((float)$c['max_amount'],0)) ?> <small>XAF</small></p><div class="criteria-facts"><span><?= e(t('Operating history','Ancienneté')) ?><strong><?= (int)$c['min_years_operating'] ?> <?= e(t('year(s)','an(s)')) ?></strong></span><span><?= e(t('Registration','Immatriculation')) ?><strong><?= e($c['requires_registration']?t('Required','Requise'):t('Flexible','Flexible')) ?></strong></span><span><?= e(t('Bank account','Compte bancaire')) ?><strong><?= e($c['requires_bank_account']?t('Required','Requis'):t('Flexible','Flexible')) ?></strong></span></div><?php if($m['matches']): ?><div class="match-status positive">✓ <?= e(t('Your profile fits the listed criteria','Votre profil correspond aux critères affichés')) ?></div><?php else: ?><div class="match-status caution">! <?= e(t('Requirements to address','Exigences à examiner')) ?><ul><?php foreach($m['reasons'] as $reason): ?><li><?= e($reason) ?></li><?php endforeach; ?></ul></div><?php endif; ?><?php if($c['other_requirements']): ?><p class="muted small"><?= e($c['other_requirements']) ?></p><?php endif; ?><?php if($hasConsent): ?><div class="pill pill-green"><?= e(t('You have shared with this lender','Vous avez partagé avec ce prêteur')) ?></div><?php else: ?><form method="post" onsubmit="return confirm('<?= e(t('Share your business profile with this lender? You can revoke access later.','Partager votre profil avec ce prêteur ? Vous pourrez révoquer l’accès plus tard.')) ?>')"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="criteria_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="action" value="consent"><label class="checkbox-label consent-check"><input type="checkbox" required> <?= e(t('I consent to sharing my business profile with this lender for review.','J’autorise le partage de mon profil professionnel avec ce prêteur pour examen.')) ?></label><button class="btn <?= $m['matches']?'btn-primary':'btn-outline' ?> full-width" type="submit"><?= e(t('Consent and share profile','Autoriser et partager le profil')) ?> →</button></form><?php endif; ?></article><?php endforeach; endif; ?></div>
<?php require __DIR__.'/includes/footer.php'; ?>
